<?php

declare(strict_types=1);

function palPageSalesList(): void { $u=palCurrentUser(); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Sales', 'page_content'=>'sales-list']); }
function palPageSalesDetail(array $rp=[]): void { $u=palCurrentUser(); $id=(int)($rp['id']??$_GET['id']??0); $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $sale=$s->get($id); if(!$sale){palJsonError('Sale not found.',404);return;} $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Invoice #'.$sale['sales_number'], 'page_content'=>'sales-detail', 'sale'=>$sale]); }
function palPageSalesForm(array $rp = []): void { $u=palCurrentUser(); $id=(int)($rp['id']??$_GET['id']??0); $sale=null; if($id>0){$s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $sale=$s->get($id); if($sale && empty($sale['invoice_number'])){$sale['invoice_number']=$sale['sales_number'];} } $db=palDb(); $tid=(int)($u['tenant_id']??0); $proj=$db->prepare("SELECT id,title FROM pal_projects WHERE tenant_id=:tid AND status IN('approved','started','ongoing','completed') ORDER BY title"); $proj->execute([':tid'=>$tid]); $clients=$db->prepare("SELECT id,name FROM pal_clients WHERE tenant_id=:tid AND is_active=1 ORDER BY name"); $clients->execute([':tid'=>$tid]); $materials=$db->prepare("SELECT m.id, m.name, m.material_code, m.price_per_unit, m.price_per_sqft, m.default_width, m.default_height, mc.name AS category_name FROM pal_materials m LEFT JOIN pal_material_categories mc ON m.category_id=mc.id WHERE m.tenant_id=:tid AND m.is_active=1 ORDER BY m.name"); $materials->execute([':tid'=>$tid]); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>$sale?'Edit Sale':'Create Sale', 'page_content'=>'sales-form', 'sale'=>$sale, 'is_edit'=>$sale!==null, 'projects'=>$proj->fetchAll(PDO::FETCH_ASSOC), 'clients'=>$clients->fetchAll(PDO::FETCH_ASSOC), 'materials'=>$materials->fetchAll(PDO::FETCH_ASSOC)]); }
function palPageCollectionList(): void { $u=palCurrentUser(); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Collections', 'page_content'=>'collections-list']); }
function palPageCollectionDetail(array $rp=[]): void { $u=palCurrentUser(); $id=(int)($rp['id']??$_GET['id']??0); $db=palDb(); $tid=(int)($u['tenant_id']??0); $stmt=$db->prepare("SELECT c.*, s.sales_number, s.net_amount AS sale_net, s.status AS sale_status, p.title AS project_title, cl.name AS client_name FROM pal_collections c LEFT JOIN pal_sales s ON c.sales_id=s.id LEFT JOIN pal_projects p ON c.project_id=p.id LEFT JOIN pal_clients cl ON c.client_id=cl.id WHERE c.id=:id AND c.tenant_id=:tid"); $stmt->execute([':id'=>$id,':tid'=>$tid]); $col=$stmt->fetch(PDO::FETCH_ASSOC); if(!$col){palJsonError('Collection not found.',404);return;} $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Collection #'.$id, 'page_content'=>'collections-detail', 'collection'=>$col]); }
function palPageCollectionForm(): void { $u=palCurrentUser(); $db=palDb(); $tid=(int)($u['tenant_id']??0); $proj=$db->prepare("SELECT id,title FROM pal_projects WHERE tenant_id=:tid AND status IN('approved','started','ongoing','completed') ORDER BY title"); $proj->execute([':tid'=>$tid]); $sales=$db->prepare("SELECT s.id, s.sales_number, s.net_amount, s.gross_amount, s.project_id, p.title AS project_title, cl.name AS client_name, COALESCE((SELECT SUM(amount) FROM pal_collections WHERE sales_id=s.id AND status='approved'),0) AS collected_amt FROM pal_sales s LEFT JOIN pal_projects p ON s.project_id=p.id LEFT JOIN pal_clients cl ON s.client_id=cl.id WHERE s.tenant_id=:tid AND s.status IN('issued','partially_paid') ORDER BY p.title, s.created_at DESC"); $sales->execute([':tid'=>$tid]); $t=__DIR__.'/../templates/project-audit-ledger/shell.disyl'; palRender($t, ['current_user'=>$u, 'page_title'=>'Record Collection', 'page_content'=>'collection-form', 'projects'=>$proj->fetchAll(PDO::FETCH_ASSOC), 'sales'=>$sales->fetchAll(PDO::FETCH_ASSOC)]); }
function palApiSalesStore(): void { palResponseGuard(function(){ $u=palCurrentUser(); palEnforceCsrf(); $data=$_POST; if(!empty($data['items']) && is_string($data['items'])){$data['items']=json_decode($data['items'],true)??[];} $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $id=$s->create($data); palAudit('pal.sale.created', (int)$u['id'], 'pal_sales', (string)$id, null, []); header('Content-Type: application/json'); echo json_encode(['ok'=>true, 'id'=>$id]); }); }
function palApiSalesUpdate(array $rp = []): void { palResponseGuard(function() use ($rp): void { $u=palCurrentUser(); palEnforceCsrf(); $id=(int)($rp['id']??$_GET['id']??$_POST['id']??0); if($id<=0){palJsonError('Invalid ID.');return;} $data=$_POST; if(!empty($data['items']) && is_string($data['items'])){$data['items']=json_decode($data['items'],true)??[];} $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $s->update($id, $data); palAudit('pal.sale.updated', (int)$u['id'], 'pal_sales', (string)$id, null, []); header('Content-Type: application/json'); echo json_encode(['ok'=>true]); }); }
function palApiSalesSendEmail(array $rp = []): void { palResponseGuard(function() use ($rp): void { $u=palCurrentUser(); palEnforceCsrf(); $id=(int)($rp['id']??0); if($id<=0){palJsonError('Invalid sales ID.');return;} $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $sale=$s->get($id); if(!$sale){palJsonError('Sale not found.',404);return;} $db=palDb(); $settings=palSettings(); $companyName=$settings['company_name']??'ZAP-ARTS Signage & Printing Solutions'; $currency=$settings['currency']??'PHP'; $sym=$currency==='PHP'?'₱':'$'; // Get client email
$clientStmt=$db->prepare("SELECT email,name,contact_person FROM pal_clients WHERE id=:id AND tenant_id=:tid"); $clientStmt->execute([':id'=>$sale['client_id'],':tid'=>(int)($u['tenant_id']??0)]); $client=$clientStmt->fetch(PDO::FETCH_ASSOC); if(!$client||empty($client['email'])||!filter_var($client['email'],FILTER_VALIDATE_EMAIL)){palJsonError('Client has no valid email address on file.');return;} $clientName=htmlspecialchars($client['name']??'Valued Client',ENT_QUOTES,'UTF-8'); $clientEmail=$client['email']; $salesNum=htmlspecialchars($sale['sales_number']??(string)$id,ENT_QUOTES,'UTF-8'); $projectTitle=htmlspecialchars($sale['project_title']??'',ENT_QUOTES,'UTF-8'); // Build line items table
$itemsHtml=''; if(!empty($sale['items'])){$itemsHtml='<table style="width:100%;border-collapse:collapse;margin-top:12px;font-size:13px;"><thead><tr style="background:#f3f4f6;"><th style="padding:8px 12px;text-align:left;border-bottom:2px solid #e5e7eb;">#</th><th style="padding:8px 12px;text-align:left;border-bottom:2px solid #e5e7eb;">Particulars</th><th style="padding:8px 12px;text-align:center;border-bottom:2px solid #e5e7eb;">QTY</th><th style="padding:8px 12px;text-align:right;border-bottom:2px solid #e5e7eb;">Unit Price</th><th style="padding:8px 12px;text-align:right;border-bottom:2px solid #e5e7eb;">Total</th></tr></thead><tbody>'; foreach($sale['items'] as $item){$itemsHtml.='<tr style="border-bottom:1px solid #e5e7eb;"><td style="padding:6px 12px;text-align:center;">'.((int)($item['sort_order']??0)).'</td><td style="padding:6px 12px;">'.htmlspecialchars($item['particulars']??'',ENT_QUOTES,'UTF-8').'</td><td style="padding:6px 12px;text-align:center;">'.number_format((float)($item['quantity']??1),2).'</td><td style="padding:6px 12px;text-align:right;">'.$sym.number_format((float)($item['price_per_unit']??0),2).'</td><td style="padding:6px 12px;text-align:right;font-weight:bold;">'.$sym.number_format((float)($item['line_total']??0),2).'</td></tr>';}$itemsHtml.='</tbody></table>';} $subject="Invoice {$salesNum} from {$companyName}"; $body="<p>Hi {$clientName},</p><p>Please find your invoice from <strong>".htmlspecialchars($companyName,ENT_QUOTES,'UTF-8')."</strong> attached below.</p><p><strong>Invoice:</strong> {$salesNum}<br><strong>Date:</strong> ".htmlspecialchars($sale['sales_date']??'',ENT_QUOTES,'UTF-8')."<br><strong>Due Date:</strong> ".htmlspecialchars($sale['due_date']??'Upon Receipt',ENT_QUOTES,'UTF-8')."<br><strong>Amount:</strong> {$sym}".number_format((float)($sale['net_amount']??0),2)."<br><strong>Status:</strong> ".htmlspecialchars($sale['status']??'',ENT_QUOTES,'UTF-8')."</p>{$itemsHtml}<p>You can view and print the full invoice here:</p><p><a href=\"".palBaseUrl()."/admin/project-audit-ledger/sales/{$id}\" style=\"display:inline-block;padding:10px 20px;background:#2563eb;color:#fff;text-decoration:none;border-radius:6px;font-size:14px;\">View Invoice</a></p>".($sale['notes']?"<hr style=\"border:none;border-top:1px solid #e5e7eb;margin:16px 0;\"><p style=\"font-size:12px;color:#6b7280;\"><strong>Notes:</strong> ".htmlspecialchars($sale['notes'],ENT_QUOTES,'UTF-8')."</p>":'')."<hr style=\"border:none;border-top:1px solid #e5e7eb;margin:16px 0;\"><p style=\"font-size:11px;color:#9ca3af;\">".htmlspecialchars($companyName,ENT_QUOTES,'UTF-8').'</p>'; $headers='MIME-Version: 1.0'."\r\n".'Content-type: text/html; charset=UTF-8'."\r\n".'From: '.$companyName.(!empty($settings['company_email'])?' <'.$settings['company_email'].'>':'')."\r\n"; $sent=mail($clientEmail, $subject, $body, $headers); if(!$sent){palJsonError('Failed to send email. Check server mail configuration.');} palAudit('pal.sale.emailed',(int)$u['id'],'pal_sales',(string)$id,null,['sent_to'=>$clientEmail]); header('Content-Type: application/json'); echo json_encode(['ok'=>true,'message'=>'Invoice emailed to '.$clientName]); }); }
function palApiCollectionStore(): void { palResponseGuard(function(){ $u=palCurrentUser(); palEnforceCsrf(); $s=new palSalesService(palDb(), (int)($u['tenant_id']??0), (int)$u['id']); $id=$s->recordCollection($_POST); palAudit('pal.collection.recorded', (int)$u['id'], 'pal_collections', (string)$id, null, []); header('Content-Type: application/json'); echo json_encode(['ok'=>true, 'id'=>$id]); }); }
